export class Soundscape {
 constructor(){this.ctx=null;this.enabled=false;this.volume=.4;this.voice=true;this.phase=5;this.lastShot=0;this.nodes=[];this.master=null;}
 async toggle(){if(this.enabled){this.enabled=false;this.master?.gain.setTargetAtTime(0,this.ctx.currentTime,.25);globalThis.speechSynthesis?.cancel();return false;}try{if(!this.ctx){this.ctx=new (window.AudioContext||window.webkitAudioContext)();this.master=this.ctx.createGain();this.master.connect(this.ctx.destination);this.master.gain.value=0;this.ambient();}await this.ctx.resume();this.enabled=true;this.setVolume(this.volume);this.tone(540,.08,'sine',.06);return true;}catch{this.enabled=false;return false;}}
 setVolume(v){this.volume=v;if(this.master)this.master.gain.setTargetAtTime(this.enabled?v:0,this.ctx.currentTime,.2);}
 ambient(){const c=this.ctx;for(const frequency of [42,63,84.15]){const o=c.createOscillator(),g=c.createGain();o.type='sine';o.frequency.value=frequency;g.gain.value=.035;o.connect(g).connect(this.master);o.start();this.nodes.push(o);}const lfo=c.createOscillator(),depth=c.createGain();lfo.frequency.value=.09;depth.gain.value=.018;lfo.connect(depth);const drone=c.createOscillator(),amp=c.createGain();drone.frequency.value=126;amp.gain.value=.025;depth.connect(amp.gain);drone.connect(amp).connect(this.master);drone.start();lfo.start();this.nodes.push(drone,lfo);}
 tone(freq,duration,type='sine',volume=.1,end=null){if(!this.enabled||!this.ctx)return;const c=this.ctx,o=c.createOscillator(),g=c.createGain();o.type=type;o.frequency.value=freq;if(end)o.frequency.exponentialRampToValueAtTime(end,c.currentTime+duration);g.gain.setValueAtTime(volume,c.currentTime);g.gain.exponentialRampToValueAtTime(.0001,c.currentTime+duration);o.connect(g).connect(this.master);o.start();o.stop(c.currentTime+duration);}
 noise(duration,volume=.15,cutoff=400){if(!this.enabled)return;const c=this.ctx,buffer=c.createBuffer(1,Math.ceil(c.sampleRate*duration),c.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=Math.random()*2-1;const source=c.createBufferSource(),filter=c.createBiquadFilter(),g=c.createGain();source.buffer=buffer;filter.type='lowpass';filter.frequency.value=cutoff;g.gain.setValueAtTime(volume,c.currentTime);g.gain.exponentialRampToValueAtTime(.0001,c.currentTime+duration);source.connect(filter).connect(g).connect(this.master);source.start();source.stop(c.currentTime+duration);}
 speak(text){if(!this.enabled||!this.voice||!globalThis.speechSynthesis)return;try{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.rate=.78;u.pitch=.55;u.volume=this.volume*.65;u.lang='en-US';speechSynthesis.speak(u);}catch{}}
 effect(type,phase){if(!this.enabled)return;if(type==='shot'){if(performance.now()-this.lastShot<120)return;this.lastShot=performance.now();this.noise(.13,.025,1600);this.tone(140,.1,'triangle',.025,60);}else if(type==='hit'){this.noise(.7,.12,450);this.tone(68,.7,'sine',.15,25);}else if(type==='nuclear'){this.noise(7,.6,230);this.tone(48,6,'sine',.4,17);this.speak('Detonation confirmed. Civilian emergency channels are no longer responding.');}else if(type==='launch'){this.noise(1.5,.1,700);this.tone(210,1.8,'sawtooth',.03,55);}else if(type==='radio'){this.noise(1.2,.025,1200);this.tone(780,.12,'sine',.04);this.speak(phase===1?'Emergency broadcast. Seek shelter immediately. This station will remain on the air as long as possible.':'All civilian traffic, clear this frequency. Unidentified contacts are approaching the exclusion zone.');}else if(type==='alarm'){for(let i=0;i<4;i++)setTimeout(()=>{this.tone(phase===1?660:440,.8,'triangle',.1,phase===1?280:350);},i*900);this.speak(`Attention. Defense condition ${phase}. ${phase===1?'Nuclear release authorized. This is not an exercise.':phase===3?'Conventional weapons free. All stations, battle positions.':'All command stations, increase readiness.'}`);}else if(type==='end'){this.tone(90,4,'sine',.12,30);this.speak('Cease fire. All surviving stations, acknowledge.');}}
}
